//! Replay the conformance vectors generated by the Python reference
//! (`scripts/gen_vectors.py`). Every case must reach the same verdict.

use std::path::PathBuf;

use mdp2p_core::*;
use serde_json::Value;

fn cases(name: &str) -> Vec<Value> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../spec/vectors")
        .join(format!("{name}.json"));
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    let doc: Value = serde_json::from_str(&text).expect("vector file is JSON");
    assert_eq!(doc["version"], 1, "unsupported vector version in {name}");
    doc["cases"].as_array().expect("cases array").clone()
}

fn s<'a>(case: &'a Value, field: &str) -> &'a str {
    case[field]
        .as_str()
        .unwrap_or_else(|| panic!("{field} is not a string in {case}"))
}

fn label(case: &Value) -> String {
    case.get("name")
        .and_then(Value::as_str)
        .unwrap_or("?")
        .to_owned()
}

#[test]
fn canonical_json_matches_reference() {
    for case in cases("canonical_json") {
        let got = canonical_json(&case["input"]).expect("canonical form");
        assert_eq!(
            String::from_utf8(got).unwrap(),
            s(&case, "canonical"),
            "{}",
            label(&case)
        );
    }
}

#[test]
fn manifest_verification() {
    for case in cases("manifest_verify") {
        let ok = verify_manifest(
            &case["manifest"],
            s(&case, "signature"),
            s(&case, "trusted_public_key"),
        );
        assert_eq!(ok, case["valid"].as_bool().unwrap(), "{}", label(&case));
        assert_eq!(
            manifest_ref(&case["manifest"]).as_deref(),
            Some(s(&case, "manifest_ref")),
            "{}",
            label(&case)
        );
    }
}

#[test]
fn content_keys() {
    for case in cases("content_key") {
        assert_eq!(
            content_key(s(&case, "uri"), s(&case, "public_key")),
            s(&case, "content_key")
        );
    }
}

#[test]
fn name_records() {
    for case in cases("name_records") {
        let result = verify_name_record(
            &case["record"],
            s(&case, "signature"),
            case["max_drift"].as_i64(),
            case["now"].as_i64().unwrap(),
        );
        assert_eq!(
            result.is_ok(),
            case["valid"].as_bool().unwrap(),
            "{}: {result:?}",
            label(&case)
        );
    }
}

#[test]
fn review_structures() {
    for case in cases("reviews") {
        let verify = match s(&case, "kind") {
            "review_record" => verify_review_record,
            "reviewer_opt_in" => verify_reviewer_opt_in,
            "review_assignment" => verify_review_assignment,
            other => panic!("unknown review kind {other}"),
        };
        let result = verify(
            &case["record"],
            s(&case, "signature"),
            case["max_drift"].as_i64(),
            case["now"].as_i64().unwrap(),
        );
        assert_eq!(
            result.is_ok(),
            case["valid"].as_bool().unwrap(),
            "{}/{}: {result:?}",
            s(&case, "kind"),
            label(&case)
        );
    }
}

#[test]
fn uris() {
    for case in cases("uris") {
        assert_eq!(
            validate_uri(s(&case, "uri")),
            case["valid"].as_bool().unwrap(),
            "{:?}",
            s(&case, "uri")
        );
    }
}

#[test]
fn paths() {
    for case in cases("paths") {
        assert_eq!(
            validate_path(s(&case, "path")),
            case["valid"].as_bool().unwrap(),
            "{:?}",
            s(&case, "path")
        );
    }
}

#[test]
fn bundle_acceptance() {
    for case in cases("bundle_checks") {
        let result = check_downloaded_bundle(
            &case["bundle"],
            s(&case, "uri"),
            s(&case, "trusted_public_key"),
            s(&case, "expected_ref"),
            case["now"].as_i64().unwrap(),
        );
        match (&result, case["reason"].as_str()) {
            (Ok(_), None) => {}
            (Err(reject), Some(code)) => assert_eq!(reject.code(), code, "{}", label(&case)),
            _ => panic!(
                "{}: got {result:?}, expected {}",
                label(&case),
                case["reason"]
            ),
        }
    }
}

#[test]
fn pins() {
    for case in cases("pins") {
        let pin = case["entry"].as_object().map(|e| Pin {
            public_key: e["public_key"].as_str().unwrap().to_owned(),
            record_timestamp: e.get("record_timestamp").and_then(Value::as_i64),
        });
        let status = check_pin(
            pin.as_ref(),
            s(&case, "public_key"),
            case["record_timestamp"].as_i64().unwrap(),
        );
        assert_eq!(status.as_str(), s(&case, "status"), "{}", label(&case));
    }
}

#[test]
fn reviewer_selection() {
    for case in cases("reviewer_selection") {
        let pool: Vec<String> = case["pool"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap().to_owned())
            .collect();
        let expected: Vec<String> = case["selected"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap().to_owned())
            .collect();
        let got = select_reviewers(
            s(&case, "content_key"),
            &pool,
            case["n"].as_u64().unwrap() as usize,
        );
        assert_eq!(got, expected, "{}", label(&case));
    }
}

#[test]
fn resolved_record_must_name_the_requested_uri() {
    let case = &cases("name_records")[0];
    let response = serde_json::json!({
        "type": "record",
        "record": case["record"],
        "signature": case["signature"],
    });
    let resolved = check_resolved_record("blog.alice", &response).expect("valid record");
    assert_eq!(
        resolved.timestamp,
        case["record"]["timestamp"].as_i64().unwrap()
    );
    assert_eq!(
        check_resolved_record("bank", &response),
        Err(ResolveError::UriMismatch)
    );
}
